insert into public.ace_quizzes(title,course_code,description) select 'Cost Accounting · Essentials','BFC3227','Cost behavior, prime costs, contribution, break-even and activity drivers.' where not exists(select 1 from public.ace_quizzes where title='Cost Accounting · Essentials');with target as (select id from public.ace_quizzes where title='Cost Accounting · Essentials' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('Which pair of costs makes up prime cost? ','["Direct materials and direct labor","Indirect materials and rent","Depreciation and marketing","Interest and taxes"]',0,'Prime costs are the directly attributable material and labor costs of production.',1),('Within a relevant range, total fixed costs usually:','["Rise in direct proportion to units","Stay approximately constant","Become zero at low output","Fall whenever output rises"]',1,'Fixed costs remain constant in total over the relevant activity range.',2),('Contribution margin per unit is:','["Price minus variable cost per unit","Total profit divided by units","Revenue minus fixed assets","Cash received minus debt"]',0,'Contribution margin is the amount each sale contributes toward fixed costs and profit.',3),('If fixed costs are KSh 20,000 and contribution per unit is KSh 200, break-even volume is:','["10 units","50 units","100 units","200 units"]',2,'Break-even units equal fixed costs divided by contribution per unit: 20,000 / 200 = 100.',4),('An appropriate activity-based costing driver for machine maintenance might be:','["Office floor color","Number of machine hours","Number of shareholders","Months since incorporation"]',1,'Machine hours often track the consumption of machine-related maintenance resources.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;insert into public.ace_quizzes(title,course_code,description) select 'Entrepreneurship · Fundamentals','BFB3202','Customer needs, feasibility, pricing and small-business cash flow.' where not exists(select 1 from public.ace_quizzes where title='Entrepreneurship · Fundamentals');with target as (select id from public.ace_quizzes where title='Entrepreneurship · Fundamentals' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('The strongest early evidence that a proposed business solves a real problem is:','["Customers repeatedly paying for a solution","A large social following with no sales","An attractive logo","A lengthy business plan alone"]',0,'Repeat purchases and payment provide stronger validation than stated interest alone.',1),('Gross profit is generally:','["Revenue minus cost of goods sold","Cash balance minus loans","Revenue plus expenses","Assets minus liabilities"]',0,'Gross profit subtracts direct cost of goods sold from sales revenue.',2),('A customer interview is most informative when the founder asks:','["Would you definitely buy my idea?","Tell me about the last time you faced this problem","Do you think my logo looks good?","Would everyone love this feature?"]',1,'Questions about past behavior uncover genuine needs and current workarounds.',3),('A profitable business can still fail when:','["It has no logo","Cash receipts arrive too late to meet obligations","It earns repeat business","It maintains records"]',1,'Cash flow timing can cause a liquidity crisis even when reported profit is positive.',4),('Before hiring many employees, a startup should first:','["Confirm repeatable demand and viable unit economics","Copy every competitor feature","Spend the entire budget on ads","Guarantee a national rollout"]',0,'Evidence of customer demand and sustainable economics reduces avoidable expansion risk.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;insert into public.ace_quizzes(title,course_code,description) select 'Human Resource Management · Core Concepts','BFB3200','Recruitment, job design, training, fair selection and feedback.' where not exists(select 1 from public.ace_quizzes where title='Human Resource Management · Core Concepts');with target as (select id from public.ace_quizzes where title='Human Resource Management · Core Concepts' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('Job analysis mainly identifies:','["Tasks, responsibilities and job requirements","The final monthly profit","The office color scheme","Only the company''s competitors"]',0,'Job analysis describes work performed and the competencies needed to perform it.',1),('Recruitment differs from selection because recruitment:','["Attracts a pool of applicants","Chooses the final candidate","Always includes dismissal","Sets the business tax rate"]',0,'Recruitment attracts candidates; selection evaluates and chooses among them.',2),('Which selection practice is generally more consistent and fair?','["Using standardized job-relevant criteria","Hiring based entirely on personal friendship","Changing questions for every candidate without reason","Ignoring job requirements"]',0,'Structured, job-relevant methods improve consistency and reduce arbitrary decisions.',3),('Training is primarily intended to:','["Improve skills needed for work","Replace all employee evaluation","Guarantee promotions","Eliminate management"]',0,'Training develops specific work-related competencies.',4),('Useful performance feedback is typically:','["Specific, timely and linked to observed behavior","Only about personality","Delayed indefinitely","Based solely on rumors"]',0,'Specific and timely feedback gives employees actionable information.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;insert into public.ace_quizzes(title,course_code,description) select 'Leadership · Team Dynamics','BFB3203','Communication, delegation, motivation and resolving disagreement.' where not exists(select 1 from public.ace_quizzes where title='Leadership · Team Dynamics');with target as (select id from public.ace_quizzes where title='Leadership · Team Dynamics' order by created_at limit 1) insert into public.ace_questions(quiz_id,prompt,options,correct_index,explanation,sort_order) select target.id,v.prompt,v.options::jsonb,v.correct_index,v.explanation,v.sort_order from target cross join (values ('Active listening includes:','["Paraphrasing to confirm understanding","Interrupting to offer an answer","Planning a rebuttal while someone speaks","Ignoring nonverbal signals"]',0,'Restating key points helps verify understanding before responding.',1),('A leader should adapt their approach when:','["Team skills and task needs vary","All people always need identical direction","Every task has the same urgency","Feedback is unnecessary"]',0,'Situational leadership recognizes different levels of competence and support needs.',2),('Effective delegation requires:','["Clear outcomes, authority and accountability","No explanation of responsibilities","Assigning all decisions to one person","Avoiding feedback altogether"]',0,'People need expectations, enough authority and a clear reporting arrangement.',3),('When team members disagree, a constructive first move is to:','["Clarify the issue and listen to both perspectives","Publicly blame one member","Ignore the conflict indefinitely","Change the project name"]',0,'Clarifying needs and facts lowers tension and focuses on solving the issue.',4),('Which feedback is most actionable?','["The report omitted two required figures; add them by Thursday","You are always bad at work","Do better somehow","Everyone is unhappy with you"]',0,'Concrete behavior and clear next steps make feedback useful.',5)) as v(prompt,options,correct_index,explanation,sort_order) on conflict(quiz_id,sort_order) do nothing;